    except Exception as e:
        return jsonify({'error': f'Error: {str(e)}'}), 500


@documentos_bp.route('/<documento_id>/archivo', methods=['GET'])
def obtener_archivo(documento_id):
    """
    Obtener/Descargar/Visualizar archivo del documento

    Soporta:
    - Imágenes: <img src="/api/documentos/{id}/archivo">
    - Videos: <video><source src="/api/documentos/{id}/archivo"></video>
    - Audio: <audio><source src="/api/documentos/{id}/archivo"></audio>
    - PDF: <iframe src="/api/documentos/{id}/archivo"></iframe>
    """
    try:
        doc_id = UUID(documento_id)
        documento = DocumentoService.obtener_documento(doc_id)

        if not documento:
            return jsonify({'error': 'Documento no encontrado'}), 404

        # Verificar que el archivo existe
        if not os.path.exists(documento.ruta_almacenamiento):
            return jsonify({'error': 'Archivo no existe en el sistema'}), 404

        # Registrar acceso
        usuario_id = obtener_usuario_id_del_token()
        DocumentoService.registrar_acceso(doc_id, usuario_id, 'descargar')

        # Servir el archivo
        # as_attachment=False permite visualizar en el navegador
        # as_attachment=True fuerza la descarga
        return send_file(
            documento.ruta_almacenamiento,
            mimetype=documento.mime_type,
            download_name=documento.nombre_original,
            as_attachment=False
        )

    except ValueError:
        return jsonify({'error': 'ID de documento inválido'}), 400
    except Exception as e:
        return jsonify({'error': f'Error al obtener archivo: {str(e)}'}), 500


@documentos_bp.route('/<documento_id>/descargar', methods=['GET'])
def descargar_archivo(documento_id):
    """
    Descargar archivo del documento (fuerza descarga)

    Igual que /archivo pero fuerza descargar en lugar de visualizar
    """
    try:
        doc_id = UUID(documento_id)
        documento = DocumentoService.obtener_documento(doc_id)

        if not documento:
            return jsonify({'error': 'Documento no encontrado'}), 404

        # Verificar que el archivo existe
        if not os.path.exists(documento.ruta_almacenamiento):
            return jsonify({'error': 'Archivo no existe en el sistema'}), 404

        # Registrar acceso
        usuario_id = obtener_usuario_id_del_token()
        DocumentoService.registrar_acceso(doc_id, usuario_id, 'descargar')

        # Servir el archivo como descarga
        return send_file(
            documento.ruta_almacenamiento,
            mimetype=documento.mime_type,
            download_name=documento.nombre_original,
            as_attachment=True
        )

    except ValueError:
        return jsonify({'error': 'ID de documento inválido'}), 400
    except Exception as e:
        return jsonify({'error': f'Error al descargar: {str(e)}'}), 500

""" Modelos SQLAlchemy para la aplicación de recuperación de información. """ from datetime import datetime from uuid import uuid4 from flask_sqlalchemy import SQLAlchemy from sqlalchemy import Index, Text, JSONB, Numeric from sqlalchemy.dialects.postgresql import UUID, ENUM
db = SQLAlchemy()
# Enums class TipoArchivo(str): """Tipos de archivo permitidos""" TEXTO = 'texto' IMAGEN = 'imagen' VIDEO = 'video' AUDIO = 'audio' DOCUMENTO = 'documento' OTRO = 'otro'
class EstadoProcesamiento(str): """Estados del procesamiento de documentos""" PENDIENTE = 'pendiente' PROCESANDO = 'procesando' COMPLETADO = 'completado' ERROR = 'error'
class Usuarios(db.Model): """Modelo para usuarios del sistema""" __tablename__ = 'usuarios' __table_args__ = {'schema': 'buscador'}
id = db.Column(UUID(as_uuid=True), primary_key=True, default=uuid4) nombre = db.Column(db.String(100), nullable=False) email = db.Column(db.String(150), unique=True, nullable=False) password_hash = db.Column(db.Text, nullable=False) activo = db.Column(db.Boolean, default=True) creado_en = db.Column(db.DateTime(timezone=True), default=datetime.utcnow) actualizado_en = db.Column(db.DateTime(timezone=True), default=datetime.utcnow, onupdate=datetime.utcnow)
