class Documentos(db.Model): """Modelo para documentos almacenados""" __tablename__ = 'documentos' __table_args__ = ( Index('idx_doc_categoria', 'categoria_id'), Index('idx_doc_usuario', 'usuario_id'), {'schema': 'buscador'} )
id = db.Column(UUID(as_uuid=True), primary_key=True, default=uuid4) usuario_id = db.Column(UUID(as_uuid=True), db.ForeignKey('buscador.usuarios.id'), nullable=True) categoria_id = db.Column(db.Integer, db.ForeignKey('buscador.categorias.id'), nullable=True) titulo = db.Column(db.String(500), nullable=False) descripcion = db.Column(db.Text) tipo = db.Column(db.String(50), default=TipoArchivo.OTRO) extension = db.Column(db.String(20)) mime_type = db.Column(db.String(100)) nombre_original = db.Column(db.String(500), nullable=False) ruta_almacenamiento = db.Column(db.Text, nullable=False) tamano_bytes = db.Column(db.BigInteger) hash_sha256 = db.Column(db.String(64)) es_publico = db.Column(db.Boolean, default=False) contenido_texto = db.Column(db.Text) idioma = db.Column(db.String(10), default='spanish') tsv_busqueda = db.Column(db.Text) # Full-text search vector metadatos = db.Column(JSONB, default={}) estado = db.Column(db.String(50), default=EstadoProcesamiento.PENDIENTE) error_mensaje = db.Column(db.Text) creado_en = db.Column(db.DateTime(timezone=True), default=datetime.utcnow) actualizado_en = db.Column(db.DateTime(timezone=True), default=datetime.utcnow, onupdate=datetime.utcnow) ultimo_acceso = db.Column(db.DateTime(timezone=True))
