def to_dict(self, include_contenido=False): data = { 'id': str(self.id), 'titulo': self.titulo, 'descripcion': self.descripcion, 'tipo': self.tipo, 'nombre_original': self.nombre_original, 'tamano_bytes': self.tamano_bytes, 'es_publico': self.es_publico, 'idioma': self.idioma, 'estado': self.estado, 'categoria_id': self.categoria_id, 'usuario_id': str(self.usuario_id) if self.usuario_id else None, 'creado_en': self.creado_en.isoformat() if self.creado_en else None, 'actualizado_en': self.actualizado_en.isoformat() if self.actualizado_en else None, } if include_contenido: data['contenido_texto'] = self.contenido_texto return data
