id = db.Column(db.Integer, primary_key=True) documento_id = db.Column(UUID(as_uuid=True), db.ForeignKey('buscador.documentos.id'), nullable=False) palabra = db.Column(db.String(200), nullable=False) peso = db.Column(db.Float, default=1.0) fuente = db.Column(db.String(50), default='manual')
