class HistorialBusquedas(db.Model): """Modelo para registrar historial de búsquedas""" __tablename__ = 'historial_busquedas' __table_args__ = ( Index('idx_hist_usuario', 'usuario_id'), {'schema': 'buscador'} )
id = db.Column(db.BigInteger, primary_key=True) usuario_id = db.Column(UUID(as_uuid=True), db.ForeignKey('buscador.usuarios.id'), nullable=True) termino = db.Column(db.Text, nullable=False) filtros = db.Column(JSONB, default={}) total_resultados = db.Column(db.Integer, default=0) ip_origen = db.Column(db.Text) buscado_en = db.Column(db.DateTime(timezone=True), default=datetime.utcnow)
