class Recomendaciones(db.Model): """Modelo para recomendaciones de documentos""" __tablename__ = 'recomendaciones' __table_args__ = ( db.UniqueConstraint('documento_id', 'recomendado_id', name='recomendaciones_unique'), {'schema': 'buscador'} )
id = db.Column(db.BigInteger, primary_key=True) documento_id = db.Column(UUID(as_uuid=True), db.ForeignKey('buscador.documentos.id'), nullable=False) recomendado_id = db.Column(UUID(as_uuid=True), db.ForeignKey('buscador.documentos.id'), nullable=False) score = db.Column(db.Float, nullable=False) algoritmo = db.Column(db.String(50), default='tfidf') calculado_en = db.Column(db.DateTime(timezone=True), default=datetime.utcnow)
# Relación con el documento recomendado documento_recomendado = db.relationship('Documentos', foreign_keys=[recomendado_id], backref='recomendado_por')
def to_dict(self): return { 'id': self.id, 'documento_id': str(self.documento_id), 'recomendado_id': str(self.recomendado_id), 'score': self.score, 'algoritmo': self.algoritmo, 'calculado_en': self.calculado_en.isoformat() if self.calculado_en else None, }
